 if(FParse::Param(FCommandLine::Get(),TEXT("KTWStreetWarLate"))){FTimerHandle CaptureSetup;GetWorldTimerManager().SetTimer(CaptureSetup,FTimerDelegate::CreateWeakLambda(this,[this](){auto* M=AKTWMatch::Find(GetWorld());if(!M)return;M->BattleSeconds=265;const FVector P=EventPoint(3);int32 N=0;for(TActorIterator<AKTWTestUnit>I(GetWorld());I;++I)if(I->Faction==0){I->SetActorLocation(P+FVector(-700,600+N++*160,100));I->IssueOrder(EKTWUnitOrder::Defend,I->GetActorLocation());}}),3.f,false);}
