 if(FParse::Param(FCommandLine::Get(),TEXT("KTWOrdersLootTest"))){FTimerHandle H;GetWorldTimerManager().SetTimer(H,this,&AKTWStreetWar::RunOrdersLootTests,3.f,false);}
 if(FParse::Param(FCommandLine::Get(),TEXT("KTWEngagementTest"))){FTimerHandle H;GetWorldTimerManager().SetTimer(H,this,&AKTWStreetWar::RunEngagementTests,3.f,false);}
 if(FParse::Param(FCommandLine::Get(),TEXT("KTWStreetWarTest"))){FTimerHandle H;GetWorldTimerManager().SetTimer(H,this,&AKTWStreetWar::RunTests,3.f,false);}
